-- 04_grammar_points.sql: Grammar Points for English Course (Spanish speakers)
INSERT INTO grammar_points (
    id, course_id, unit_id, slug, cefr_level, ordinal, title, short_explanation, rule_text, common_trap, examples
)
VALUES
    ('b0000001-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000001', 'to-be-subject-pronouns', 'A1', 1, 'Subject pronouns and to be', 'Use am/is/are for identity and origin.', 'I am, you are, he/she/it is, we are, they are. Unlike Spanish, English always needs the subject pronoun.', 'Dropping the subject pronoun (*am student instead of I am a student).', '["I am a student.","Where are you from?","She is from Madrid."]'::jsonb),
    ('b0000001-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000002', 'questions-with-do', 'A1', 2, 'Yes/no questions and question words', 'Form questions with do/does or question words.', 'Questions with do/does/did invert nothing else: Do you speak English? Question words: what, where, when, why, how, who.', 'Forgetting do/does (*Speak you English?) or doubling it (Where do you are from?).', '["What is your name?","Do you speak English?","Where do you live?"]'::jsonb),
    ('b0000001-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000003', 'present-simple-third-person', 'A1', 3, 'Present simple and third person -s', 'Conjugate the present simple for habits and routines.', 'He/she/it adds -s or -es: he works, she watches, it rains. Frequency adverbs go before the verb: I usually get up at seven.', 'Forgetting the third person -s (*she work) or misplacing usually (*I get up usually at seven).', '["I get up at seven.","She works from Monday to Friday.","What time do you have breakfast?"]'::jsonb),
    ('b0000001-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000004', 'would-like-articles', 'A1', 4, 'Polite requests, would like, and articles', 'Order politely with would like and match a/an/the.', 'Use I would like (I''d like) for polite requests. a before consonant sounds, an before vowel sounds, the for specific things.', 'Saying I want to a waiter instead of the softer I''d like; using an before consonant sounds (*an coffee).', '["I''d like a coffee with milk, please.","A table for two.","How much is the menu?"]'::jsonb),
    ('b0000001-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000005', 'there-is-prepositions', 'A1', 5, 'There is/are and prepositions of place', 'Locating objects and places.', 'Use there is + singular / there are + plural for existence. Prepositions: next to, across from, behind, between, on the corner.', 'Using there is with plurals (*there is two banks) or literal translations of Spanish prepositions.', '["Is there a pharmacy near here?","The museum is next to the park.","Turn left at the corner."]'::jsonb),
    ('b0000001-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000007', 'past-simple-regular-irregular', 'A2', 6, 'Past simple: regular and irregular verbs', 'Describing completed actions in the past.', 'Regular verbs add -ed (worked, traveled). Irregular verbs change form: go→went, buy→bought, see→saw. Negatives and questions use did: Did you go? I didn''t go.', 'Mixing -ed onto irregular verbs (*goed, *buyed) or keeping the past form after did (*Did you went?).', '["Yesterday I went out with my friends.","I saw a movie on Saturday.","We ate an amazing paella."]'::jsonb),
    ('b0000001-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000009', 'going-to-have-to', 'A2', 7, 'Going to and have to', 'Expressing near-future plans and obligation.', 'Be going to + verb expresses future plans and intentions. Have to + verb expresses necessity and obligation.', 'Forgetting be before going to (*I going to travel) or to after have (*I have work tomorrow).', '["I''m going to travel to Mexico.","I have to work tomorrow.","What are you going to do this weekend?"]'::jsonb),
    ('b0000001-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000013', 'past-simple-vs-past-continuous', 'B1', 8, 'Past simple vs past continuous narration', 'Contrasting completed events with ongoing backgrounds.', 'Past continuous (was/were + -ing) sets the scene and background; past simple narrates the events that happened. While + continuous, when + simple.', 'Using past simple for backgrounds (*it rained when I left instead of it was raining when I left).', '["It was sunny when I got to the beach.","While I was studying, the phone rang.","As a kid, I played football every day."]'::jsonb),
    ('b0000001-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000019', 'conditionals-second', 'B2', 9, 'Second conditional and hypotheticals', 'Talking about imagined present or future situations.', 'If + past simple, would + verb: If I had more time, I would take a cooking class. Use were for all persons in formal hypotheticals: If I were you.', 'Using would in the if-clause (*If I would have time) or mixing with first conditional logic.', '["If I had more time, I would take a cooking class.","If I were you, I would accept the offer.","She would travel more if she could."]'::jsonb),
    ('b0000001-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000021', 'reported-speech-passive', 'B2', 10, 'Reported speech and passive voice', 'Relaying what was said and emphasizing the action.', 'Reported speech shifts tenses back (say→said, is→was) and pronouns: He said he was busy. Passive: be + past participle — The report was written by the team.', 'Forgetting the tense shift (*She said she is tired) or the be in passives (*The report written by the team).', '["They said the meeting was postponed.","The bridge was built in 1995.","He told me he had finished the report."]'::jsonb)
ON CONFLICT (course_id, slug) DO UPDATE SET
    cefr_level = EXCLUDED.cefr_level,
    ordinal = EXCLUDED.ordinal,
    title = EXCLUDED.title,
    short_explanation = EXCLUDED.short_explanation,
    rule_text = EXCLUDED.rule_text,
    common_trap = EXCLUDED.common_trap,
    examples = EXCLUDED.examples;
